"""Compute the order of the permutation group generated by a puzzle's move tables.

    python scripts/group_order.py                              # Maltese Gear Cube, 8.82e69
    python scripts/group_order.py --puzzle tangram_extreme     # 4.75e28

Maltese Gear Cube point set (192 points, ``point_permutations``):
    0..95     sticker positions
    96..191   gear orientations: gear slot j with orientation r  ->  96 + 4*j + r

A move is a permutation of these points. Gear colours are attributes that travel
with the gear, so they add no extra points. Any other puzzle is taken through the
labelled point model of core/perm_model.py, which gives the same group. The result is
|G| for the position-permutation group; the number of distinct coloured states
reachable from the goal is |G| / |Stab(goal)| and is at most |G|.
"""
from __future__ import annotations

import argparse
import sys
import time
from pathlib import Path

import numpy as np

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))

from core.perm_model import build_point_model  # noqa: E402
from puzzles.maltese_gear.puzzle import build_maltese_gear_puzzle  # noqa: E402
from puzzles.registry import PUZZLES, get_puzzle  # noqa: E402

N_STICKER = 96
N_SLOT = 24
N_POINTS = N_STICKER + 4 * N_SLOT  # 192


def point_permutations(puzzle) -> list[list[int]]:
    perms: list[list[int]] = []
    for m in range(puzzle.num_moves):
        idx = puzzle.idx[m]
        add = puzzle.add[m]
        arr = np.full(N_POINTS, -1, dtype=np.int64)
        # Sticker content at source position idx[i] moves to destination i.
        for i in range(N_STICKER):
            arr[idx[i]] = i
        # Gear slot j receives the gear from slot k = idx[120 + j] - 120, with the
        # orientation shifted by add[120 + j].
        for j in range(N_SLOT):
            k = int(idx[120 + j]) - 120
            a = int(add[120 + j])
            for r in range(4):
                arr[N_STICKER + 4 * k + r] = N_STICKER + 4 * j + ((r + a) % 4)
        assert sorted(arr.tolist()) == list(range(N_POINTS)), f"move {m} is not a permutation"
        perms.append(arr.tolist())
    return perms


def model_permutations(puzzle) -> list[list[int]]:
    """Moves as permutations (image form) of the labelled points of core/perm_model.py."""
    model = build_point_model(puzzle)
    return [np.argsort(g).tolist() for g in model.gens]


def main() -> None:
    from sympy.combinatorics import Permutation, PermutationGroup

    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--puzzle", choices=sorted(PUZZLES), default="maltese")
    args = ap.parse_args()
    if args.puzzle == "maltese":
        perms = point_permutations(build_maltese_gear_puzzle())
    else:
        perms = model_permutations(get_puzzle(args.puzzle).build())
    gens = [Permutation(p) for p in perms]
    t0 = time.time()
    group = PermutationGroup(gens)
    order = group.order()
    elapsed = time.time() - t0
    print(f"degree {len(perms[0])}, generators {len(gens)}")
    print(f"|G| = {order}")
    print(f"log10|G| = {np.log10(float(order)):.3f}")
    print(f"time {elapsed:.1f}s")


if __name__ == "__main__":
    main()
